    assertPaneId(paneId);
    const [windowId] = await this.command(`display -p -t ${paneId} '#{window_id}'`);
    if (!/^@\d+$/.test(windowId ?? "")) throw new Error(`kein Fenster zu Pane ${paneId}: ${windowId}`);
    await this.merkeFenster(windowId);
